'use strict';

/**
* Evaluate the binary logarithm (base two) of a single-precision floating-point number.
*
* @module @stdlib/math-base-special-log2f
*
* @example
* var log2f = require( '@stdlib/math-base-special-log2f' );
*
* var v = log2f( 4.0 );
* // returns 2.0
*
* v = log2f( 8.0 );
* // returns 3.0
*
* v = log2f( 0.0 );
* // returns -Infinity
*
* v = log2f( Infinity );
* // returns Infinity
*
* v = log2f( NaN );
* // returns NaN
*
* v = log2f( -4.0 );
* // returns NaN
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
